{"command":"cd /testbed/migration-recon && python3 - <<'EOF'
import sqlite3
for name in ("source", "target"):
    p = f"databases/{name}.db"
    con = sqlite3.connect(f"file:{p}?mode=ro", uri=True)
    print(f"=== {name}.db ===")
    rows = con.execute("SELECT type, name, sql FROM sqlite_master ORDER BY type, name").fetchall()
    for typ, n, sql in rows:
        print(f"-- {typ}: {n}")
        print(sql)
        if typ == "table":
            try:
                c = con.execute(f'SELECT COUNT(*) FROM "{n}"').fetchone()[0]
                print(f"-- count: {c}")
            except Exception as e:
                print(f"-- count error: {e}")
        print()
    con.close()
EOF"}

